import json,sys,re
def txt(s,n=400):
    s=re.sub(r'\s+',' ',str(s))
    return s[:n]+('…' if len(s)>n else '')
for line in sys.stdin:
    line=line.strip()
    if not line: continue
    try: e=json.loads(line)
    except: continue
    ts=e.get('timestamp','')[11:19]
    t=e.get('type')
    m=e.get('message') or {}
    c=m.get('content')
    if t=='user':
        if isinstance(c,str):
            print(f"{ts} USER: {txt(c,900)}")
        elif isinstance(c,list):
            for b in c:
                if b.get('type')=='text':
                    print(f"{ts} USER: {txt(b.get('text'),900)}")
                elif b.get('type')=='tool_result':
                    cc=b.get('content')
                    if b.get('is_error'):
                        print(f"{ts}   ERR: {txt(cc,300)}")
    elif t=='assistant':
        for b in (c or []):
            if b.get('type')=='text':
                print(f"{ts} ASST: {txt(b.get('text'),700)}")
            elif b.get('type')=='tool_use':
                print(f"{ts}   >{b.get('name')}: {txt(json.dumps(b.get('input'))[:250],250)}")

